#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Questlog setup. Connects the app to your own Supabase database,
# creates your sign-in, and gives the cloud ping timer what it needs.
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "$0")"
mkdir -p "$HOME/.questlog" && chmod 700 "$HOME/.questlog"
ENV_FILE="$HOME/.questlog/env"
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"

# api_headers KEY: curl header args for a Supabase key (new sb_ keys go in apikey only).
api_headers() {
  if [[ "$1" == eyJ* ]]; then printf -- '-H\napikey: %s\n-H\nAuthorization: Bearer %s\n' "$1" "$1"
  else printf -- '-H\napikey: %s\n' "$1"; fi
}
supa_get() { # supa_get KEY PATH → body, fails on HTTP errors
  local key="$1" path="$2" args=()
  while IFS= read -r line; do args+=("$line"); done < <(api_headers "$key")
  curl -fsS "${args[@]}" "${SUPABASE_URL%/}$path"
}

TOTAL_STAGES=6

banner "Questlog setup"

stage "Create your Supabase project"
say "Supabase is the free database that keeps your quests in sync between phone and laptop."
open_url "https://supabase.com/dashboard/new"
step "Sign up or sign in (GitHub sign-in is quickest)."
step "Create a new project named questlog. Region: East US (North Virginia)."
step "Pick a database password and save it in your password manager. This wizard doesn't need it."
step "Wait until the project finishes setting up (a minute or two)."
pause "Press Enter when the project dashboard is ready."

stage "Copy the project address and keys"
open_url "https://supabase.com/dashboard/project/_/settings/api"
step "Under Data API, copy the Project URL (https://….supabase.co)."
ask SUPABASE_URL "Paste the Project URL:"
SUPABASE_URL="${SUPABASE_URL%/}"
write_env SUPABASE_URL "$SUPABASE_URL"
open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
step "Copy the Publishable key (starts sb_publishable_). If you only see Legacy keys, copy anon public."
ask SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
step "Under Secret keys, reveal and copy the secret key (starts sb_secret_). Legacy: service_role."
note "This one is private. It stays on your Mac and in GitHub's encrypted secrets."
ask_secret SUPABASE_SECRET_KEY "Paste the secret key (hidden):"
write_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
if supa_get "$SUPABASE_PUBLISHABLE_KEY" "/rest/v1/" >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} Supabase answered with those values."
else
  warn "Supabase didn't accept the URL or publishable key. Re-run ./setup.sh to fix them."
fi
pause

stage "Create the Questlog table"
pbcopy < supabase/schema.sql
say "The table setup SQL is now on your clipboard."
open_url "https://supabase.com/dashboard/project/_/sql/new"
step "Paste into the SQL editor (Cmd-V) and click Run."
step "You should see: Success. No rows returned."
pause "Press Enter after it ran."
if supa_get "$SUPABASE_SECRET_KEY" "/rest/v1/docs?select=id&limit=1" >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} The docs table is ready."
else
  warn "Couldn't reach the docs table yet. If the SQL failed, run it again, then re-run ./setup.sh."
fi
pause

stage "Create your sign-in"
open_url "https://supabase.com/dashboard/project/_/auth/users"
step "Click Add user → Create new user."
step "Enter your email and a strong password. This is how you'll sign in to Questlog on your phone and laptop."
step "Tick Auto Confirm User, then Create user."
ask QUESTLOG_EMAIL "Which email did you use?"
write_env QUESTLOG_EMAIL "$QUESTLOG_EMAIL"
QUESTLOG_USER_ID=$(supa_get "$SUPABASE_SECRET_KEY" "/auth/v1/admin/users?per_page=200" 2>/dev/null | python3 -c '
import json, sys
email = sys.argv[1].strip().lower()
data = json.load(sys.stdin)
users = data.get("users", data) if isinstance(data, dict) else data
print(next((u["id"] for u in users if (u.get("email") or "").lower() == email), ""))
' "$QUESTLOG_EMAIL" 2>/dev/null || true)
if [[ -n "$QUESTLOG_USER_ID" ]]; then
  say "${GREEN}✓${RESET} Found your user: $QUESTLOG_USER_ID"
else
  step "Couldn't look it up automatically. Click your user in the list and copy its User UID."
  ask QUESTLOG_USER_ID "Paste the User UID:"
fi
write_env QUESTLOG_USER_ID "$QUESTLOG_USER_ID"
open_url "https://supabase.com/dashboard/project/_/auth/providers"
step "So nobody else can make an account: turn off \"Allow new users to sign up\" and click Save."
pause "Press Enter when that's saved."

stage "Notification keys and the cloud timer"
say "Creating the keys that let Questlog send pings to your phone."
VAPID_PUBLIC_KEY=$(_existing VAPID_PUBLIC_KEY || true)
VAPID_PRIVATE_KEY=$(_existing VAPID_PRIVATE_KEY || true)
if [[ -z "$VAPID_PUBLIC_KEY" || -z "$VAPID_PRIVATE_KEY" ]]; then
  [[ -d node_modules ]] || npm install --no-audit --no-fund >/dev/null
  keys=$(node -e 'const w=require("web-push");const k=w.generateVAPIDKeys();console.log(k.publicKey+" "+k.privateKey)')
  VAPID_PUBLIC_KEY="${keys% *}"; VAPID_PRIVATE_KEY="${keys#* }"
else
  note "Keeping your existing notification keys, so phones already set up keep working."
fi
QUESTLOG_TZ=$(readlink /etc/localtime | sed 's#.*/zoneinfo/##')
write_env VAPID_PUBLIC_KEY "$VAPID_PUBLIC_KEY"
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
write_env VAPID_SUBJECT "mailto:$QUESTLOG_EMAIL"
write_env QUESTLOG_TZ "$QUESTLOG_TZ"
say "Saving the timer's settings as encrypted GitHub secrets:"
set_secret SUPABASE_URL "$SUPABASE_URL"
set_secret SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
set_secret QUESTLOG_USER_ID "$QUESTLOG_USER_ID"
set_secret QUESTLOG_TZ "$QUESTLOG_TZ"
set_secret VAPID_PUBLIC_KEY "$VAPID_PUBLIC_KEY"
set_secret VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
set_secret VAPID_SUBJECT "mailto:$QUESTLOG_EMAIL"
pause

stage "Connect the app and publish"
cat > docs/config.js <<EOF
// Filled in by setup.sh. These values are safe to publish: the key only works for a signed-in user's own rows.
window.QUESTLOG_CONFIG = {
  supabaseUrl: "$SUPABASE_URL",
  supabaseKey: "$SUPABASE_PUBLISHABLE_KEY",
  vapidPublicKey: "$VAPID_PUBLIC_KEY",
};
EOF
say "${GREEN}✓${RESET} Wrote docs/config.js (public values only)."
if node scripts/questlog.mjs dump >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} Claude's helper can read your Questlog."
else
  warn "The helper couldn't read Questlog. Check the secret key and user ID, then re-run ./setup.sh."
fi
if confirm "Publish the connected app to GitHub Pages now?"; then
  git add docs/config.js
  git commit -q -m "Connect Questlog to its database" || note "Nothing new to commit."
  git push -q && say "${GREEN}✓${RESET} Published. The site updates within a minute or two."
else
  SKIPPED+=("Publish docs/config.js: git add docs/config.js && git commit -m 'Connect Questlog' && git push")
fi
pause

finish
say "Next: tell Claude setup is done. It will move your existing Questlog data over and test a ping."
printf '\n'
